"""Evidence-backed progress reports and one chronological root index; no scores invented."""
from common48_v3 import *
def main():
 q=read(R/'outputs/qualification_v1/qualification.json');assert q['status']=='QUALIFIED_REAL_PROCESS_MEMORY_SCREEN';s=read(R/'outputs/supervisor_v1.json');selection=read(R/'outputs/control_v1/selection.json');manifest=read(R/'data/MANIFEST.json');fits=[read(p/'fit_summary.json') for p in sorted((R/'outputs/fits').iterdir()) if (p/'fit_summary.json').exists()];utc=now();completed=len(fits);updates=sum(f['updates'] for f in fits);pending='Training/evaluation pending as of this timestamp; consult live supervisor/status files. No EVAL performance or new-method claim is available.'
 evidence=f'UTC {utc}. Frozen16-fit queue, {completed} completed fits / {updates} completed-fit updates at this snapshot. Qualification24 discarded updates excluded. Actual server supervisor pid{s["pid"]}; state{s["status"]}. '+pending
 (R/'literature_review.md').write_text('# C48 literature and development boundary\n\n'+(R/'RESEARCH_INTAKE.md').read_text(encoding='utf-8').split('## New primary-source facts',1)[1]+'\n\nRead original selected source and numerical solver; archive hashes and all98 Git blobs verified. This evidence changes baseline choice, not the novelty verdict.\n',encoding='utf-8')
 table=['| Arm | Trainable / nominal parameters | Discarded CPU step seconds | Discarded CUDA step seconds |','|---|---:|---:|---:|']
 for method in METHODS:
  cpu=next(t for t in q['timings'] if t['method']==method and t['device']=='cpu');gpu=next((t for t in q['timings'] if t['method']==method and t['device']=='cuda'),None);table.append(f"| {method} | {cpu['trainable_parameters']} / {cpu['nominal_parameters']} | {cpu['median_seconds']:.5f} | {gpu['median_seconds']:.5f} |")
 registry='# C48 execution registry\n\n'+evidence+'\n\n'+'\n'.join(table)+'\n\nArticle-linked model9b573c4bed5efee9fe9c6b765044dbd506b5bf07 and solver4888c63dc84e966f6c6553277adc3851a2cca4fc. Classes/solver execute unchanged; calendar wrapper, scalar residual GRU head, new data/task and training schedule disclosed in PROTOCOL.md. Cross-benchmark adaptation, not original-paper headline reproduction. No new proposed method.\n\nCPU selected from actual discarded throughput; global package/environment untouched. Same DATA/seed minibatch schedule across four arms, fixed/learned delays share initial weights. GRU and complete-history ridge are the strong ordinary controls; NODE is a weak diagnostic ablation.\n\n'
 for entry in selection['cases']:registry+=f"{entry['case']}: TRAIN{entry['train_origins']}, VAL{entry['val_origins']}; selected ridge{entry['selected']['ridge']:g}, VAL MSE{entry['selected']['val_mse']:.7f}. These are VAL selections, not EVAL results.\n\n"
 (R/'baseline_registry.md').write_text(registry,encoding='utf-8')
 results='# C48 results — formal comparison pending\n\n'+evidence+'\n\nQualified known linear DDE maximum errors at h1/24,1/48,1/96day: '+str(q['linear_exponential_max_errors'])+'. Independent Heun maximum errors: '+str(q['independent_heun_max_errors'])+'. Neural delay gradient absolute discrepancies: '+str([v['absolute_error'] for v in q['neural_delay_gradient_checks']])+'. These are solver/gradient qualifications, not evidence of forecasting advantage.\n\nFrozen real-process data: ETTh1 OT and Jena2016 temperature,96 observed hours to48 future hours. TRAIN-only scaling, chronological split boundaries, missing Jena hours retained and incomplete windows excluded. Reusing raw bytes is disclosed; this contract differs from C40 and its scores must not be merged into a controlled ranking.\n\n'
 for f in fits:results+=f"Completed {f['tag']}: updates{f['updates']}, selected{f['selected_step']}, VAL MSE{f['selected_val_mse']:.7f}, cap{f['hard_cap_hit']}. No TEST score.\n\n"
 results+='All16 selections must be sealed before test opening. Evaluation queue then performs VAL numerical/history diagnostics, locked forecasting and real-prefix continuation, followed by independent raw-source/window/NumPy-model/score verification. Real origins are temporally dependent; deterministic mean forecasts do not certify a stochastic world law.\n';(R/'experimental_results.md').write_text(results,encoding='utf-8')
 (R/'negative_evidence.md').write_text('# C48 unsupported claims and inherited negatives\n\nC47 fixed-feature Laplace/hybrid is deprioritized after adverse bistable scores against full likelihood. It is not retuned here. C46 simple observation/dynamics factorization also lacked a stable neural interaction benefit.\n\nLearned delays, state-dependent delays, recurrent memory, observer/transition separation and test-time dynamics adaptation have established sources. No novelty claim follows from adding memory. Static associative key/slot retrieval can provide useful learned priors; it must not automatically be described as episode-specific history retention, nor attacked as universally lacking history if its base predictor has context.\n\n'+pending+'\n\nA weak NODE losing would not establish a new gap. If complete-history ridge or GRU covers the useful behavior, extra memory machinery needs a distinct benefit. A delay model winning would establish only an existing mechanism\'s utility under this protocol. Input information, effective budget, parameter counts and numerical accuracy must accompany any future attribution.\n\nThe package import/JAX issue was a pre-training dependency repair, not a scientific failure. Native source bytes are unchanged.\n',encoding='utf-8')
 (R/'hypothesis_space.md').write_text('# C48 competing hypotheses\n\nH0: ordinary full-history regression or recurrent state already provides useful future evolution and real-observation continuation. Primary controls test this; do not infer new-method need from NODE alone.\n\nH1: explicit delayed evidence improves learning efficiency over a recurrent state. Compare complete frozen fits, parameter/cost records and independent future metrics. This is an existing mechanism, not a novelty claim.\n\nH2: learning delay locations matters beyond adding fixed memory. Fixed/learned NDDE share source, initial delays/weights, data, loss and schedule; retain both results.\n\nH3: any apparent advantage is a solver, interpolation, clock, boundary, information or training artifact. Numerical qualification, postselection VAL refinement, independent source-window and model replay address distinct parts; active training caps still limit interpretation.\n\nH4: a static learned memory prior substitutes for dynamic evidence retention. Retrieval equations alone cannot establish this; current history-gradient profiles only characterize one functional, with cancellation possible. No new static-bank model comparison is claimed.\n\nH5: a distinct framework-level memory learning interaction has independent-domain utility. Not tested by these existing arms; a concrete new method and fresh confirmatory protocol remain required.\n',encoding='utf-8')
 (R/'research_ideas.md').write_text('# C48 development lead, not accepted direction\n\nCurrent lead: understand which learned memory representation remains useful when a time-series model must continue physical evolution without observations and then use real new observations. The executed comparison adds a source-grounded explicit-memory family to prior strong controls on two real processes. It is designed to decide the next mechanism question, not maximize a dataset score.\n\nNo new architecture is proposed merely because delay equations or observers exist. A known-component framework remains eligible if a distinct necessary learning interaction and independent utility can be demonstrated. Generic SSM expressivity is not an automatic veto.\n\nFallback: temporal measurement-support transfer, where interval averages are different operators from point samples. Integrated GP and field-layer alignment are close existing mechanisms; its current novelty is unresolved and no new-method effect is claimed. Unknown-regime adaptation remains another unselected lead with substantial prior art.\n\nDo not recommend any of these as a completed final direction. Finish the frozen memory screen, inspect actual failure attribution, and choose a new interaction only if it survives strong controls.\n',encoding='utf-8')
 final='# C48 — final research direction remains unaccepted\n\n**Research Question:** Which memory construction gives a reusable time-series world model useful state evolution and observed continuation beyond competent ordinary regression/recurrent controls? This is the present failure-discovery question, not an established novel gap.\n\n**Evidence:** '+evidence+'\n\n**Existing Methods:** NDDE/state-dependent DDE, GRU/latent states, OSSM and adaptive-world-model work cover major components. The current source-grounded comparison has no new method.\n\n**Proposed Idea:** None accepted. Explicit memory is a development lead; a distinct learning interaction remains to be discovered from results.\n\n**Falsification:** If GRU/ridge covers utility, a new memory requirement is not supported. If only the weaker NODE loses, no novel gap follows. A delay improvement alone is an existing-method result, not a framework contribution.\n\n**Feasibility:** Authorized server, source+solver pinned and numerically qualified, actual CPU/GPU timings, two real processes and16 fresh fits. Single5090 available; this small-core workload is faster on CPU.\n\n**Next Experiment:** Complete all frozen fits; score sealed EVAL plus real24-hour-prefix continuation; independently reconstruct raw windows and every disclosed model forecast in NumPy. Use failures and strong controls to determine the next distinct framework mechanism.\n\nAccepted final directions0, overall goal ACTIVE_UNACHIEVED. No publication-ready or universal probability-law claim.\n';(R/'final_research_direction.md').write_text(final,encoding='utf-8')
 (R/'CURRENT_STATE.md').write_text('# C48 progress snapshot\n\n'+evidence+'\n\nActive common48_v3.py and qualification_v3; see VERIFICATION_SUPPLEMENT.md for the pre-training import/head repair and exact evaluator versions. Do not restart based on a stale snapshot. Inspect actual PIDs plus supervisor and fit status files first.\n',encoding='utf-8')
 dump(R/'PROGRESS_REPORT_MANIFEST.json',{'utc':utc,'status':'TRAINING_IN_PROGRESS_GOAL_UNACHIEVED','completed_fits_at_snapshot':completed,'files':{p.name:sha(p) for p in R.iterdir() if p.suffix=='.md'},'source_sha256':sha(__file__)})
 # Add a dated chronological index once; previous root bytes remain archived.
 tag='<!-- cycle48-progress-index-start -->';receipt=R/'ROOT_INDEX_RECEIPTS.json'
 if not receipt.exists():
  archive=R/'outputs/root_history_v1';archive.mkdir();records=[]
  for name in ['CURRENT_RESEARCH_STATUS.md','literature_review.md','baseline_registry.md','experimental_results.md','negative_evidence.md','hypothesis_space.md','research_ideas.md','final_research_direction.md']:
   path=ROOT/name;old=path.read_bytes();assert tag.encode() not in old;(archive/name).write_bytes(old);header=f'''{tag}
# C48：真实过程的记忆机制比较已启动，最终方向仍未确定

UTC {utc}。上一轮C47为PROGRESS，本轮新增论文对应源码/求解器、独立数值资格和正式16-fit比较。研究单位仍是WorldTS层次的可复用时间序列world-model框架，数据只作机制证据。整体ACTIVE_UNACHIEVED，接受最终方向0。

两份Zenodo作者存档与98个Git blobs已逐项匹配。原生NDDE/求解器通过独立Heun递推和延迟梯度核查；CPU实际更快，24discarded updates不计正式训练。新的96h→48h协议使用ETTh1/Jena真实过程、相同允许信息；强对照含GRU及full-history ridge，NODE只作弱消融。此为跨任务适配，非论文headline复现或新方法。

此时16组队列已启动，完成{completed}组；完整结果和EVAL独立重放仍待完成。不得把VAL、资格或局部进度写成最终收益。评估程序等待全部选择固定后才打开TEST。见[冻结协议](cycle48/PROTOCOL.md)、[真实执行状态](cycle48/CURRENT_STATE.md)、[机会图及创新边界](cycle48/RESEARCH_INTAKE.md)。精确当前进度以服务器supervisor/实际进程为准，勿因观察超时重启。

已有可学习延迟、state-dependent DDE、observer和自适应world model均纳入边界；不把增加memory本身当创新。C47当前Laplace方案与C46简单factorization继续降优先级，C44原查询协议保持INCOMPLETE、不重启。

以下为历史。
<!-- cycle48-progress-index-end -->

''';assert path.read_bytes()==old;path.write_bytes(header.encode('utf-8')+old);records.append({'path':name,'before':hashlib.sha256(old).hexdigest(),'after':sha(path)})
  dump(receipt,{'utc':utc,'files':records,'goal_complete':False})
 print(json.dumps({'status':'PROGRESS_REPORTS_SAVED','completed_fits_at_snapshot':completed,'completed_fit_updates':updates,'accepted_final_directions':0,'EVAL_scored':False}),flush=True)
if __name__=='__main__':main()
